"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["66119"],{16032(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.referencia_temporal_fatos_fase_inexistente","status":422,"titulo":"A fase da refer\xeancia temporal de fatos n\xe3o pertence (mais) ao cronograma"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.referencia_temporal_fatos_fase_inexistente","requisitos":[],"oQueAconteceu":["A refer\xeancia temporal dos fatos do processo conta a idade do candidato a partir\\ndo in\xedcio ou do fim de uma fase, mas essa fase n\xe3o pertence (mais) ao cronograma\\ndo processo. Isso acontece quando o cronograma \xe9 redefinido depois que a\\nrefer\xeancia foi escolhida e a fase escolhida sai dele.","A confer\xeancia s\xf3 vale quando alguma regra do processo cita a faixa et\xe1ria do\\ncandidato. A recusa acontece ao tentar congelar uma vers\xe3o (publica\xe7\xe3o inicial ou retifica\xe7\xe3o em ato \xfanico), e nada \xe9 congelado."],"comoResolver":["Defina de novo a refer\xeancia temporal dos fatos, escolhendo uma fase que esteja no\\ncronograma atual, ou outro tipo de refer\xeancia. Alternativamente, devolva ao\\ncronograma a fase que servia de refer\xeancia.","Se nenhuma regra deveria usar a faixa et\xe1ria, remover a regra que a cita tamb\xe9m\\nafasta a recusa.","Em processo j\xe1 publicado, a altera\xe7\xe3o \xe9 feita numa retifica\xe7\xe3o. Depois, repita a\\nopera\xe7\xe3o recusada."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);